1174: 		ctx->root = root;
1175: 		return 0;
1176: 	}
1177: 
1178: 	/*
1179: 	 * No such thing, create a new one.  name= matching without subsys
1180: 	 * specification is allowed for already existing hierarchies but we
1181: 	 * can't create new one without subsys specification.
