996: static int check_cgroupfs_options(struct fs_context *fc)
997: {
998: 	struct cgroup_fs_context *ctx = cgroup_fc2context(fc);
999: 	u16 mask = U16_MAX;
1000: 	u16 enabled = 0;
1001: 	struct cgroup_subsys *ss;
1002: 	int i;
1003: 
1004: #ifdef CONFIG_CPUSETS
1005: 	mask = ~((u16)1 << cpuset_cgrp_id);
1006: #endif
1007: 	for_each_subsys(ss, i)
1008: 		if (cgroup_ssid_enabled(i) && !cgroup1_ssid_disabled(i))
1009: 			enabled |= 1 << i;
1010: 
1011: 	ctx->subsys_mask &= enabled;
1012: 
1013: 	/*
1014: 	 * In absence of 'none', 'name=' and subsystem name options,
1015: 	 * let's default to 'all'.
1016: 	 */
1017: 	if (!ctx->subsys_mask && !ctx->none && !ctx->name)
1018: 		ctx->all_ss = true;
1019: 
1020: 	if (ctx->all_ss) {
1021: 		/* Mutually exclusive option 'all' + subsystem name */
1022: 		if (ctx->subsys_mask)
1023: 			return invalfc(fc, "subsys name conflicts with all");
1024: 		/* 'all' => select all the subsystems */
1025: 		ctx->subsys_mask = enabled;
1026: 	}
1027: 
1028: 	/*
1029: 	 * We either have to specify by name or by subsystems. (So all
1030: 	 * empty hierarchies must have a name).
1031: 	 */
1032: 	if (!ctx->subsys_mask && !ctx->name)
1033: 		return invalfc(fc, "Need name or subsystem set");
1034: 
1035: 	/*
1036: 	 * Option noprefix was introduced just for backward compatibility
1037: 	 * with the old cpuset, so we allow noprefix only if mounting just
1038: 	 * the cpuset subsystem.
1039: 	 */
1040: 	if ((ctx->flags & CGRP_ROOT_NOPREFIX) && (ctx->subsys_mask & mask))
1041: 		return invalfc(fc, "noprefix used incorrectly");
1042: 
1043: 	/* Can't specify "none" and some subsystems */
1044: 	if (ctx->subsys_mask && ctx->none)
1045: 		return invalfc(fc, "none used incorrectly");
1046: 
1047: 	return 0;
