1071: 	 * require capabilities to set release agent.
1072: 	 */
1073: 	if (ctx->release_agent &&
1074: 	    ((ctx->ns->user_ns != &init_user_ns) || !capable(CAP_SYS_ADMIN))) {
1075: 		ret = -EINVAL;
1076: 		goto out_unlock;
1077: 	}
1078: 
1079: 	added_mask = ctx->subsys_mask & ~root->subsys_mask;
1080: 	removed_mask = root->subsys_mask & ~ctx->subsys_mask;
1081: 
1082: 	/* Don't allow flags or name to change at remount */
